import re
base = "IP/STD_cell/ics55_LLSC_H7C_V1p10C100/"
files = {
 "H7CH": base+"ics55_LLSC_H7CH/cdl/ics55_LLSC_H7CH.cdl",
 "H7CL": base+"ics55_LLSC_H7CL/cdl/ics55_LLSC_H7CL.cdl",
 "H7CR": base+"ics55_LLSC_H7CR/cdl/ics55_LLSC_H7CR.cdl",
}
texts = {}
for k,f in files.items():
    texts[k] = open(f).read()

def norm(t):
    t = re.sub(r'_(hvt|lvt|svt)_lp', '_X_lp', t)
    t = re.sub(r'ICSN55H7(H|L|R)VT', 'LIB', t)
    return t

n = {k: norm(t) for k,t in texts.items()}
print("H7CH vs H7CL normalized diff lines:", sum(1 for a,b in zip(n["H7CH"].splitlines(), n["H7CL"].splitlines()) if a!=b))
import difflib
d = list(difflib.unified_diff(n["H7CH"].splitlines(), n["H7CL"].splitlines(), lineterm='', n=0))
print("unified diff entries:", len(d))
for line in d[:20]: print(line)
EOF
